/** Contrato que exportaba L002R2 (EXPORT CARGAMOV1, ENLACE_6D, CARGASALDOS, CONTROLES). */
public interface RegistroContableApi {
    int cargaMovimiento(byte[] datos);      // CARGAMOV1
    int enlace6d(byte[] datos);             // ENLACE_6D: solo instancia S408
    int cargaSaldos(byte[] datos);          // CARGASALDOS
    int controles(byte[] datos);            // CONTROLES: consola de operación
}

@Service
@RequiredArgsConstructor
public class RegistroContableService implements RegistroContableApi, SmartLifecycle {

    private final CanalesContables canales;          // LOGS[0:9], DESS[0:9], SDOS[0:9]
    private final AltaDisponibilidad ha;             // VERIFICA_HA, testigos FINS500 / FINS408
    private final ReentrantLock cambiaFecha;         // CAMBIA_FECHA
    private volatile boolean levantaP015 = true;     // HI_4 := LEVANTA_P015 := TRUE
    private volatile boolean finS408, finS500;
    private volatile boolean running;

    @Override
    public void start() {                            // equivale a LEVANTA; VERIFICA_HA
        if (cambiaFecha.isHeldByCurrentThread()) cambiaFecha.unlock();
        canales.levanta();                           // fechas abiertas desde L001/CONTROL, apertura de archivos
        ha.verifica();                               // reanuda el disparo de P150 tras una caída
        running = true;                              // FREEZE(CONTROL, PROC_CONTROL)
    }

    @Override
    public void stop() {                             // BAJA
        running = false;
        canales.cierraTodo();
    }

    @Override public boolean isRunning() { return running; }
}

private final ReentrantLock e1 = new ReentrantLock(true);   // interlock E1 de movimientos
private final ReentrantLock e2 = new ReentrantLock(true);   // interlock E2 de saldos
private final P002Properties props;                          // sistema que atiende esta instancia

/** CARGAMOV1: ACQUIREL(E1); CARGAMOV; el EPILOG LIBERA garantiza RELINQUISHL(E1). */
@Override
public int cargaMovimiento(byte[] datos) {
    adquiere(e1);
    try {
        return cargaMov(datos);
    } finally {
        e1.unlock();                                     // EPILOG PROCEDURE LIBERA
    }
}

/** ENLACE_6D: alias restringido a la instancia del S408; cualquier otra devuelve 1. */
@Override
public int enlace6d(byte[] datos) {
    return props.sistema() == 408 ? cargaMovimiento(datos) : Resultado.SISTEMA_NO_VALIDO;   // 1
}

private static final Duration TIEMPO = Duration.ofSeconds(3);     // TIEMPO = 3#
private static final Duration AVISO_DESDE = Duration.ofSeconds(15);

/** ACQUIREL(E): espera sin límite; a partir de 15 s avisa quién tiene el lock. */
private void adquiere(ReentrantLock e) {
    long total = 0;
    try {
        while (!e.tryLock(TIEMPO.toSeconds(), TimeUnit.SECONDS)) {
            total += TIEMPO.toSeconds();
            if (total > AVISO_DESDE.toSeconds()) {
                log.warn("Llevo {} Seg en espera del Lock, La mezcla {} Lo tiene tomado",
                         total, dueño(e));                 // LOCKSTATUS(E).[47:24]
            }
            if (total > props.esperaMaximaLock().toSeconds()) {
                throw new LockNoDisponibleException(total);  // nuevo: COBOL/ALGOL espera indefinidamente
            }
        }
    } catch (InterruptedException ie) {
        Thread.currentThread().interrupt();
        throw new LockNoDisponibleException(total);
    }
}

/** Hasta 10 días contables abiertos a la vez: el movimiento va al canal de su fecha contable. */
private int resuelveCanal(MovimientoGl mov, int resultadoPrevio) {
    while (cambiaFecha.isLocked()) esperaCorta();             // WHILE LOCKSTATUS(CAMBIA_FECHA) ... WAIT((.3))

    if (mov.sistema() != props.sistema()) return -Resultado.SISTEMA_NO_VALIDO;   // RESULT := 1
    if (resultadoPrevio != 0) return -resultadoPrevio;

    OptionalInt canal = IntStream.rangeClosed(0, 9)
            .filter(i -> mov.fechaContable().equals(canales.fechaDia(i)))   // FEC_DIA[I_I]
            .findFirst();
    if (canal.isPresent()) return canal.getAsInt();               // NUMDIAC1
    if (mov.funcion() == 96) return CANAL_NO_REQUERIDO;           // fin de S500 no necesita canal
    return -Resultado.FECHA_NO_ABIERTA;                           // RESULT := 4
}

private int despacha(MovimientoGl mov, int canal) {
    return switch (mov.funcion()) {
        case 1      -> cargaMemory(mov, canal);          // alta de movimiento
        case 2      -> elimina(mov, canal);              // baja lógica
        case 11     -> inicia(mov, canal);
        case 12     -> termina(mov, canal);
        case 21     -> eliminaPorProceso(mov, canal);
        case 22     -> eliminaPorAutorizacion(mov, canal);
        case 31, 32 -> cambiaModoEscritura(mov, canal);  // REBLOCKADE
        case 96     -> { if (props.sistema() == 408) { finS500 = true; fechaP150 = mov.fechaContable(); } yield 0; }
        case 97     -> preFinal(mov);
        case 98     -> finDeMovimientos(mov);
        default     -> Resultado.FUNCION_NO_VALIDA;      // ELSE: RESULT := 2
    };
}

/** FUNCION 98: cierra los diez canales y, en la instancia S408, reenvía el cierre a la del S500. */
private int finDeMovimientos(MovimientoGl mov) {
    canales.cierraTodos();                               // CIERRALOG(0..9)
    if (props.sistema() == 408) {
        finS408 = true;
        ha.marcaTestigo("FINS408", fechaS151);           // archivo testigo de alta disponibilidad
        fechaP150 = mov.fechaContable();
        int r = registroS500.enlace8d(MovimientoGl.cierre(96, 1, 500, fechaP150));   // ENLACE_8D
        if (r != 0) throw new ReenvioCierreS500Exception(r);   // nuevo: en ALGOL el resultado se ignora
    }
    return finalYSincroniza();                           // FINAL
}

@Component
@RequiredArgsConstructor
public class ValidadorMovimiento {

    private final CatalogoClavesS080 claves;   // ACLAVES, cargado por CARGACVES

    /** DFVALIDA: devuelve el código de rechazo o 0. */
    public int valida(MovimientoGl m) {
        if (m.clave(1) == 0) return 3;                                   // sin primera clave
        for (int i = 1; i <= 5 && m.clave(i) > 0; i++) {
            if (claves.columna(m.clave(i)) <= 0) return 3;                // clave no catalogada
        }
        int r = 0;
        for (int i = 1; i <= 5 && m.importe(i).signum() > 0; i++) {
            int ind = claves.indicador(m.clave(i));
            if ((ind == 2 || ind == 3) && m.sucursalPromotora() <= 0) r = 5;
            if ((ind == 1 || ind == 3) && m.sucursalInicial() <= 0)   r = 6;
        }
        if (r != 0) return r;                                            // ALGOL conserva el último código
        if (m.origen() < 1 || m.origen() > 3) return 10;
        if (m.moneda() <= 0) return 14;
        return 0;
    }
}

/** GRABALOG: header en el registro 0 y autorización = NIVLOG + 1 (posición física en el archivo MOV). */
private int cargaMemory(MovimientoGl mov, int canal) {
    if (mov.funcion() == 1) {
        int r = validador.valida(mov);
        if (r != 0) return r;
    }
    CanalDia c = canales.canal(canal);
    if (c.nivelLog() == 0) {
        c.escribeHeader("HD", c.fecha());                   // "HD" + FECDIA 8 dígitos + ceros
    }
    long autorizacion = c.nivelLog() + 1;                   // DFAUT y DFAUTFAN
    mov.asignaAutorizacion(autorizacion);
    c.escribe(autorizacion, mov);                           // resto de GRABALOG: bloque MOV y, si hay, DES

    // CARGAMEMORY: si quedan menos de 300 registros libres, el archivo crece 20 000 (MOV) o 5 000 (DES).
    c.ampliaSiHaceFalta(300, props.ampliacionMov(), props.ampliacionDes());
    return 0;
}

@Component
@RequiredArgsConstructor
public class LanzadorProcesosGl {

    private final JobLauncher launcher;
    private final Job p015Intradia, p016Nocturno, p025ConsolidaSaldos;
    private final P002Properties props;

    /** Se ejecuta tras confirmar el registro, fuera del lock E1 (en ALGOL corre dentro, con WAIT((3))). */
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    @Async
    public void onMovimientoRegistrado(MovimientoRegistrado ev) {
        var c = ev.canal();
        boolean diaVigente = !c.fecha().isBefore(ev.fechaProceso());     // FEC_DIA >= FECPROC
        boolean antesCorte = ev.hora().isBefore(props.cortaNocturno());  // HORA < 200000

        if (ev.funcion() < 98 && diaVigente && ev.tipoProceso() < 16 && levantaP015) {
            if (!c.p015Activo()) lanza(p015Intradia, c);
            if (!c.p016Activo() && antesCorte) lanza(p016Nocturno, c);
        }
        if (!p025Activo() && c.fecha().equals(ev.fechaS151()) && ev.funcion() == 1
                && ev.tipoProceso() > 15 && ev.statusBdSdo() < 99) {
            lanza(p025ConsolidaSaldos, c);                               // consolidación de saldos
        }
    }
}

private int actNivel;   // ACT_NIVEL

private void despuesDeRegistrar(MovimientoGl mov, int resultado, byte[] original) {
    if (resultado == 0) {
        actNivel++;
        boolean altaOBaja = mov.funcion() == 1 || mov.funcion() == 2;
        if (!altaOBaja || actNivel == props.sincronizaCada()) {     // 1000
            control.actualizaNiveles(canales.niveles());            // ACTNIVEL hacia L001/CONTROL
            actNivel = 0;
        }
    } else {
        errores.write(RegistroRechazado.de(original, resultado));  // WRITE(ERRORES1[NIVERROR1], 90, ...)
    }
}

